private static function me(Actor $a):array{$db=Db::wpdb();$employees=Db::table('employees');$designations=Db::table('designations');$e=$db->get_row($db->prepare("SELECT e.id,e.employee_code,e.full_name,e.mobile,e.email,e.designation_code,e.reporting_designation_code,d.name AS designation_name,e.assigned_branch_id,e.reporting_employee_id,re.employee_code AS reporting_employee_code,re.full_name AS reporting_employee_name FROM {$employees} e LEFT JOIN {$designations} d ON d.company_id=e.company_id AND d.code=e.designation_code AND d.status='active' LEFT JOIN {$employees} re ON re.company_id=e.company_id AND re.id=e.reporting_employee_id AND re.status='active' WHERE e.id=%d",$a->employeeId),ARRAY_A);if($e)$e['reporting_category']=HierarchyScope::reportingCategoryForCode((string)$e['designation_code'],(string)($e['reporting_designation_code']??''));return['employee'=>$e,'company_id'=>$a->companyId,'assigned_branch_id'=>$a->assignedBranchId,'branch_ids'=>$a->branchIds,'branch_selector_visible'=>$a->selectorVisible(),'capabilities'=>$a->capabilities];}

private static function bootstrap(Actor $a):array{return['me'=>self::me($a),'company'=>self::companyProfile($a),'branches'=>OrganizationService::branches($a),'navigation'=>NavigationProjection::make($a),'features'=>['batch_mode'=>BusinessPolicy::BATCH_MODE,'owner_decision_required'=>BusinessPolicy::OWNER_DECISION_REQUIRED,'api_contract'=>ApiContract::VERSION]+ApiContract::featureFlags()];}

private static function companyProfile(Actor $a):array{$db=Db::wpdb();$company=$db->get_row($db->prepare("SELECT id,name FROM ".Db::table('companies')." WHERE id=%d AND status='active'",$a->companyId),ARRAY_A);if(!$company)return['id'=>$a->companyId,'name'=>'ERP Company','address'=>'','phone'=>'','email'=>'','website'=>''];$settings=(array)$db->get_results($db->prepare("SELECT setting_key,setting_value FROM ".Db::table('settings')." WHERE company_id=%d AND setting_key IN ('branding_address','branding_phone','branding_email','branding_website')",$a->companyId),ARRAY_A);$map=[];foreach($settings as$row)$map[(string)$row['setting_key']]=(string)($row['setting_value']??'');return['id'=>(int)$company['id'],'name'=>(string)$company['name'],'address'=>$map['branding_address']??'','phone'=>$map['branding_phone']??'','email'=>$map['branding_email']??'','website'=>$map['branding_website']??''];}

private static function products(Actor $a):array{Guard::any($a,[Capabilities::PRODUCT_VIEW,Capabilities::PRODUCT_MANAGE,Capabilities::SALES_CREATE,Capabilities::PURCHASE_CREATE,Capabilities::DAILY_SELF,Capabilities::DAILY_OTHERS,Capabilities::INVENTORY_VIEW]);$db=Db::wpdb();return(array)$db->get_results($db->prepare("SELECT p.*,cr.mrp,cr.sale_price,cr.ho_amount,cr.bm_profit,cr.salary_fund,cr.office_expense,cr.points FROM ".Db::table('products')." p LEFT JOIN ".Db::table('product_commercial_revisions')." cr ON cr.id=(SELECT id FROM ".Db::table('product_commercial_revisions')." c2 WHERE c2.company_id=p.company_id AND c2.product_id=p.id AND c2.status='active' AND c2.effective_from<=%s ORDER BY c2.effective_from DESC,c2.id DESC LIMIT 1) WHERE p.company_id=%d AND p.status='active' ORDER BY p.name",Db::now(),$a->companyId),ARRAY_A);}

private static function audit(Actor $a,int $limit):array{Guard::cap($a,Capabilities::AUDIT_VIEW);$limit=max(1,min(500,$limit));return(array)Db::wpdb()->get_results(Db::wpdb()->prepare("SELECT * FROM ".Db::table('audit_log')." WHERE company_id=%d ORDER BY id DESC LIMIT %d",$a->companyId,$limit),ARRAY_A);}

private static function arr($r,string $key):array{$v=$r->get_param($key);return is_array($v)?$v:[];}
private static function readBranch($r,Actor $a):int{$v=$r->get_param('branch_id');return($v===null||$v==='')?$a->assignedBranchId:(int)$v;}
private static function ni(mixed $v):?int{return($v===null||$v==='')?null:(int)$v;}
private static function nf(mixed $v):?float{return($v===null||$v==='')?null:(float)$v;}
private static function boolParam($r,string $key):bool{$v=$r->get_param($key);if(is_bool($v))return $v;if(is_int($v)||is_float($v)){if((int)$v===1)return true;if((int)$v===0)return false;}if(is_string($v)){if(in_array(strtolower(trim($v)),['true','1'],true))return true;if(in_array(strtolower(trim($v)),['false','0',''],true))return false;}if($v===null)return false;throw new DomainException('Invalid boolean value for '.$key.'.','boolean_invalid',422);}

 private static function arrBody($r):array{$v=$r->get_json_params();return is_array($v)?$v:[];}
}